# owner: platform
"""Snap clock times to a fixed step for payroll and label the result."""

from typing import Iterable, List

from hourglass.models import Span
from hourglass.parsing import format_span

MINUTES_PER_HOUR = 60

def _check_step(step_minutes: int) -> None:
    if step_minutes <= 0 or MINUTES_PER_HOUR % step_minutes:
        raise ValueError(f"step must divide an hour evenly, got {step_minutes}")

def _snap(minute: int, step_minutes: int) -> int:
    """Nearest multiple of the step. Exact halves round up."""
    return (minute + step_minutes // 2) // step_minutes * step_minutes

def _snap_span(span: Span, step_minutes: int) -> Span:
    return Span(_snap(span.start, step_minutes), _snap(span.end, step_minutes))

def _label(span: Span) -> str:
    hours, minutes = divmod(span.minutes, MINUTES_PER_HOUR)
    return f"{format_span(span)} ({hours}h {minutes}m)"

# ---
def label_rounded_spans(spans: Iterable[Span], step_minutes: int) -> List[str]:
    """Snap spans to the step and label them, like 09:00-17:15 (8h 15m)."""
    _check_step(step_minutes)
    return [_label(_snap_span(span, step_minutes)) for span in spans]

