# owner: platform
import unittest

from hourglass.models import Span
from hourglass.rounding import label_rounded_spans

class LabelTests(unittest.TestCase):
    def test_times_already_on_the_step_are_unchanged(self):
        self.assertEqual(
            label_rounded_spans([Span(540, 1020)], 15), ["09:00-17:00 (8h 0m)"]
        )

    def test_rounds_to_nearest_step(self):
        self.assertEqual(
            label_rounded_spans([Span(544, 1028)], 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_exact_half_rounds_up(self):
        self.assertEqual(
            label_rounded_spans([Span(545, 1025)], 10), ["09:10-17:10 (8h 0m)"]
        )

    def test_step_of_one_keeps_minutes(self):
        self.assertEqual(
            label_rounded_spans([Span(61, 125)], 1), ["01:01-02:05 (1h 4m)"]
        )

    def test_each_span_gets_a_label_in_order(self):
        spans = [Span(780, 1020), Span(540, 720)]
        self.assertEqual(
            label_rounded_spans(spans, 60),
            ["13:00-17:00 (4h 0m)", "09:00-12:00 (3h 0m)"]
        )

    def test_end_at_midnight_is_labelled_as_2400(self):
        self.assertEqual(
            label_rounded_spans([Span(1430, 1440)], 15), ["23:45-24:00 (0h 15m)"]
        )

    def test_span_that_rounds_to_nothing_raises(self):
        with self.assertRaises(ValueError):
            label_rounded_spans([Span(1438, 1440)], 15)

    def test_empty_list_gives_empty_list(self):
        self.assertEqual(label_rounded_spans([], 15), [])

class StepTests(unittest.TestCase):
    def test_step_must_be_positive(self):
        for step in (0, -15):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    label_rounded_spans([Span(540, 600)], step)

    def test_step_must_divide_an_hour_evenly(self):
        for step in (7, 45, 120):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    label_rounded_spans([Span(540, 600)], step)

    def test_bad_step_raises_even_without_spans(self):
        with self.assertRaises(ValueError):
            label_rounded_spans([], 7)
